      : (response && Array.isArray(response.data)) ? response.data : [];
  return list
    .filter((c) => c && (c.id !== undefined && c.id !== null))
    .map((c) => ({ id: String(c.id), name: String(c.name || ''), status: String(c.status || '') }));
}

