  if (platform === 'smartlead') {
    return { method: 'POST', url: SMARTLEAD_BASE + '/campaigns/' + assertId(campaignId) + '/status', body: { status: 'PAUSED' } };
  }
  return { method: 'POST', url: INSTANTLY_BASE + '/campaigns/' + assertId(campaignId) + '/pause', body: {} };
