/* ------------------------------------------------------------------------ */
/* Evaluation                                                               */
/* ------------------------------------------------------------------------ */

/**
 * Judge one campaign against the thresholds.
 * @returns {{decision:string, breaches:object[], rates:object, denominator:number|null, denominatorSource:string, reason:string}}
